package payments

import (
	"context"
	"errors"
	"testing"
)

// Shared links carry hints, not authority. Exercise the real resolver against a
// disposable database without creating an invoice, sending an OTP, or placing a
// new member. Both binary links must remain compatible with the canonical MP
// codes generated by the portal, including sponsors with an old invitation link.
func TestSharedReferralHintsPreserveOwnerAndSidePostgres(t *testing.T) {
	if testing.Short() {
		t.Skip("isolated PostgreSQL testcontainer")
	}
	pool, cleanup := pgContainer(t)
	defer cleanup()
	ctx := context.Background()
	if _, err := pool.Exec(ctx, `
	 INSERT INTO mlm.person(id,first_name,last_name,email,phone_number,status)
	 OVERRIDING SYSTEM VALUE VALUES
	 (9101,'Synthetic','Sponsor','shared-sponsor@example.test','0','active'),
	 (9102,'Synthetic','Other','other-sponsor@example.test','0','active'),
	 (9103,'Synthetic','New','shared-buyer@example.test','0','pending');
	 INSERT INTO mlm.affiliate(id,person_id,parent_id,position,sponsor_id,status,invitation_link)
	 OVERRIDING SYSTEM VALUE VALUES
	 (9101,9101,NULL,NULL,NULL,'active','@LegacySponsor'),
	 (9102,9102,9101,'L',9101,'active','other-sponsor');`); err != nil {
		t.Fatal("seed isolated referral fixture", err)
	}

	snapshot := func() string {
		t.Helper()
		var state string
		if err := pool.QueryRow(ctx, `SELECT jsonb_build_object(
		 'people',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM mlm.person p),
		 'affiliates',(SELECT jsonb_agg(to_jsonb(a) ORDER BY id) FROM mlm.affiliate a),
		 'referrals',(SELECT jsonb_agg(to_jsonb(r) ORDER BY email_norm) FROM payments.registration_referral r)
		)::text`).Scan(&state); err != nil {
			t.Fatal("read isolated referral snapshot", err)
		}
		return state
	}
	before := snapshot()
	h := &Handler{store: NewStore(pool), companyRoot: 999}

	for _, code := range []string{"@LegacySponsor", "@legacysponsor", "MP9101", "mp9101"} {
		for _, side := range []string{"L", "R"} {
			t.Run(code+"/"+side, func(t *testing.T) {
				sponsor, recordedCode, recordedSide, err := h.resolveCheckoutPlacement(ctx,
					"shared-buyer@example.test", Buyer{PersonID: 9103}, code, side)
				if err != nil || sponsor == nil || *sponsor != 9101 || recordedCode != code || recordedSide != side {
					t.Fatalf("new member hint lost or reassigned: sponsor=%v code=%q side=%q err=%v", sponsor, recordedCode, recordedSide, err)
				}
			})
		}
	}
	if _, _, _, err := h.resolveCheckoutPlacement(ctx, "shared-buyer@example.test", Buyer{PersonID: 9103}, "missing-sponsor", "R"); !errors.Is(err, ErrInvalidReferralCode) {
		t.Fatal("invalid shared link must not silently use the company root", err)
	}

	// An already-positioned member retains their authoritative sponsor even if
	// the browser has a different member's shared link or a stale invalid hint.
	affiliateID, originalSponsor := int64(9102), int64(9101)
	for _, code := range []string{"MP9102", "missing-sponsor"} {
		sponsor, recordedCode, recordedSide, err := h.resolveCheckoutPlacement(ctx,
			"other-sponsor@example.test", Buyer{PersonID: 9102, AffiliateID: &affiliateID, SponsorAffiliateID: &originalSponsor}, code, "R")
		if err != nil || sponsor == nil || *sponsor != originalSponsor || recordedCode != "" || recordedSide != "" {
			t.Fatalf("shared hint changed an existing network identity: sponsor=%v code=%q side=%q err=%v", sponsor, recordedCode, recordedSide, err)
		}
	}
	if after := snapshot(); after != before {
		t.Fatal("resolving referral hints changed people, tree, or registration attribution")
	}
}
